open("profiles.sql","w").write(f"""-- Way of Vanilla: player personality templates (curated from the Humanlike 75, Vanilla-adapted).
START TRANSACTION;
DELETE FROM mod_ollama_chat_personality_templates WHERE `key` NOT LIKE 'BIO\\_%' AND `key` NOT LIKE 'BIOX\\_%';
INSERT INTO mod_ollama_chat_personality_templates (`key`, `prompt`, `manual_only`) VALUES
{rows};
DELETE FROM mod_ollama_chat_personality;
COMMIT;
""")
